INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (0, 8235, 'boot-snailjob.yml', 'DEFAULT_GROUP', '', 'snail-job:\n  # 任务调度服务器信息\n  server:\n    # 服务器IP地址（或域名）；集群时建议通过 nginx 做负载均衡\n    host: 127.0.0.1\n    # 服务器通讯端口（不是后台管理页面服务端口）\n    port: 17888\n  # 命名空间 【上面配置的空间的唯一标识】\n  namespace: ${environment}\n  # 接入组名【上面配置的组名称】注意: 若通过注解配置了这里的配置不生效\n  group: test_sj_group\n  # 接入组 token 【上面配置的token信息】\n  token: SJ_t3GFbbDCpmznt9M9Pp62GYJecE6S9q9H\n  # 客户端绑定IP，必须服务器可以访问到；默认自动推断，在服务器无法调度客户端时需要手动配置\n#   host: 127.0.0.1\n  # 客户端通讯端口，默认 17889\n  port: 17888', '98273eac0085a8b48d780114ea27b161', '2026-09-02 10:23:47', '2026-09-02 18:23:48', NULL, '192.168.65.1', 'I', 'local', '');
