INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (0, 8600, 'com.maozi.system.user.api.rpc.RpcUserInfoService', 'mapping', '', 'dubbo-maozi-cloud-system-service', 'a1163d568e61a377fbd7b85e2380de41', '2026-09-06 09:28:13', '2026-09-06 17:28:14', NULL, '172.18.0.16', 'I', 'dev', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (5576, 8601, 'cloud-dubbo.yml', 'DEFAULT_GROUP', '', 'dubbo:\n  # registry.register-mode: instance/interface/all\n  application: \n    name: dubbo-${spring.application.name}\n    register-mode: instance\n    version: ${project.version:main}\n    serialize-check-status: DISABLE\n    check-serializable: false\n  scan:\n    base-packages: com.maozi.${application-project-abbreviation}.*.api.impl.rpc\n  protocol:\n    # name: tri\n    name: dubbo\n    port: ${application-dubbo-port}\n  provider:\n    filter: applicationDubboContextLoadFilter\n    prefer-serialization: hessian2\n    serialization: hessian2\n  consumer:\n    check: false\n    timeout: 30000\n    retries: 0\n    filter: applicationDubboContextTransmitFilter\n  registry:\n    address: nacos://${spring.cloud.nacos.discovery.server-addr}?namespace=${spring.cloud.nacos.discovery.namespace}\n', 'f4c08b2dc84b662658e8f47d25e5d444', '2026-09-06 09:31:27', '2026-09-06 17:31:27', 'nacos', '192.168.65.1', 'U', 'local', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (5575, 8602, 'cloud-default.yml', 'DEFAULT_GROUP', '', 'server:\n  port: ${application-port}\n  error.path: /application/error\n  # compression:\n  #   enabled: true\n  #   min-response-size: 1024\n  #   mime-types: application/json,application/xml,text/html,text/xml,text/plain\n\nspring: \n  main:\n    banner-mode: off\n    log-startup-info: false\n  web:\n    resources:\n      add-mappings: false\n  mvc: \n    throw-exception-if-no-handler-found: true\n    pathmatch.matching-strategy: ant_path_matcher\n  jackson: \n    time-zone: GMT+8\n    date-format: yyyy-MM-dd HH:mm:ss\n    default-property-inclusion: NON_NULL\n\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n  client:\n    config:\n      default:\n        connectTimeout: 30000\n        readTimeout: 30000\n  compression:\n    request:\n      # 开启请求数据的压缩功能\n      enabled: true\n      # 最小压缩值标准，当数据大于 1024 才会进行压缩\n      min-request-size: 1024\n      # 压缩类型\n      mime-types: text/xml,application/xml,application/json\n    response:\n      enabled: true\n\nlogging: \n  level: \n    root: ERROR\n    com.maozi: INFO\n    org.apache.dubbo.registry: OFF\n    org.apache.dubbo.remoting: OFF\n    com.xxl.job.core.handler.impl.MethodJobHandler: INFO\n    org.springframework.cloud.stream.binding.StreamListenerMessageHandler: INFO', '1c20936a9d151a1bcceaebef71c0ae40', '2026-09-06 09:31:54', '2026-09-06 17:31:54', 'nacos', '192.168.65.1', 'U', 'local', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (5647, 8603, 'maozi-cloud-system-service.yml', 'DEFAULT_GROUP', '', 'project:\n  title: 系统服务\n  details: 管理 用户、角色、权限、系统配置 等功能\n\napplication-port: ${APPLICATION_PORT:0}\napplication-dubbo-port: ${APPLICATION_DUBBO_PORT:-1}\n\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n# application-datasource-db-name: maozi-cloud-system-local-db\n\napplication-project-whitelist: /config/system/get\n\napplication-project-system: \n  projectName: 小猫子脚手架\n  corporationName: 小猫子网络科技有限公司\n  icon: http://dummyimage.com/100x100\n  environment: ${environment}\n  description: 基于 Spring Cloud Alibaba + Dubbo 的一站式分布式解决方案开源封装，内置分布式应用开发所需全套组件，统一团队代码风格，保障代码质量，让开发者专注业务逻辑，实现高效快速开发。\n  copyright: 本网站所有权归《${application-project-system.corporationName}》所有，请勿抄袭和抄袭\n\nspring.servlet.multipart: \n  # 上传大小限制（默认仅 1MB）\n  max-file-size: 1MB\n  \noss:\n  # 路由到阿里云处理器\n  store-type: aliyun\n  aliyun:\n    access-key-id: ${ALIYUN_CLIENT_ID}\n    access-key-secret: ${ALIYUN_CLIENT_SECRET}\n    region: cn-beijing\n    endpoint: https://oss-cn-beijing.aliyuncs.com\n    bucket: maozi-cloud-bucket\n    #domain:                  # 可选，CDN 自定义域名', '54b12fde82d99a02b3209f1e503ce1ae', '2026-09-06 09:32:10', '2026-09-06 17:32:11', 'nacos', '192.168.65.1', 'U', 'local', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (5648, 8604, 'maozi-cloud-oauth-service.yml', 'DEFAULT_GROUP', '', 'project:\n  title: 认证授权服务\n  details: 管理 三方认证授权、客户端 等功能\n\napplication-port: ${application-dev-port:3000}\napplication-dubbo-port: ${application-dev-dubbo-port:20880}\n\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n\napplication-datasource-db-name: maozi-cloud-oauth-local-db\n\napplication-redis-database: 3\n\n# application-project-whitelist: ', 'f935fd0f9f09aae31b732bf292de4e6b', '2026-09-06 09:32:18', '2026-09-06 17:32:18', 'nacos', '192.168.65.1', 'U', 'local', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (5649, 8605, 'maozi-cloud-gateway-service.yml', 'DEFAULT_GROUP', '', 'project:\n  title: 网关服务\n  details: 处理 流量分发、黑白名单、流控 等功能\n\napplication-port: ${application-dev-port:1000}\n\nspring: \n  cloud:\n    sentinel:\n      filter:\n        enabled: false\n      datasource:\n        gw-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: ${spring.cloud.nacos.config.namespace}\n            dataId: ${spring.application.name}-gw-flow\n            groupId: SENTINEL_GROUP\n            rule-type: gw-flow\n        gw-api-group:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: ${spring.cloud.nacos.config.namespace}\n            dataId: ${spring.application.name}-gw-api-group\n            groupId: SENTINEL_GROUP\n            rule-type: gw-api-group\n    gateway:\n      discovery:\n        locator:\n          enabled: true\n\n\n      default-filters:\n      - StripPrefix=1\n      - name: Retry\n        args:\n          retries: 1\n          methods: GET,POST\n          statuses: BAD_GATEWAY,GATEWAY_TIMEOUT,SERVICE_UNAVAILABLE\n          series: INFORMATIONAL\n          exceptions: java.net.ConnectException,org.springframework.cloud.gateway.support.NotFoundException\n\n\n      routes: \n        - id: MAOZI-CLOUD-SYSTEM-SERVICE\n          uri: lb://maozi-cloud-system-service\n          predicates:\n          - Path=/system/**\n\n        - id: MAOZI-CLOUD-OAUTH-SERVICE\n          uri: lb://maozi-cloud-oauth-service\n          predicates:\n          - Path=/oauth/**\n\n        - id: MAOZI-CLOUD-AI-SERVICE\n          uri: lb://maozi-cloud-ai-service\n          predicates:\n          - Path=/ai/**\n          # filters:\n          #- StripPrefix=1\n          # - WSProtocolFilter\n\n      # default-filters:\n      #   - name: Hystrix\n      #     args:\n      #       name: default\n      #       #转发地址\n      #       fallbackUri: \'forward:/fallback\'\n      #   - name: Retry\n      #     args:\n      #       #重试次数，默认值是 3 次\n      #       retries: 3\n      #       #HTTP 的状态返回码\n      #       statuses: BAD_GATEWAY,BAD_REQUEST\n      #       #指定哪些方法的请求需要进行重试逻辑，默认值是 GET 方法\n      #       methods: GET,POST', 'c2e1487f8e26868f309b6dc48fb950bb', '2026-09-06 09:35:41', '2026-09-06 17:35:41', 'nacos', '192.168.65.1', 'U', 'local', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (5650, 8606, 'maozi-cloud-monitor-service.yml', 'DEFAULT_GROUP', '', 'project:\n  title: 监控服务\n  details: 监控 JVM、运行状态、配置、连接中间件状态 等功能\n\napplication-port: ${application-dev-port:2000}\n\nspring:\n  security:\n    user:\n      name: admin\n      password: admin\n  boot:\n    admin:\n      discovery: \n        services: maozi-cloud-*\n      # ui:\n      #   external-views:\n\n      #     - label: \"Nacos\"\n      #       url: \"http://localhost:8848/nacos\"\n      #       iframe: true\n      #       order: 2002\n\n      #     - label: \"Grafana\"\n      #       url: \"http://maozi-cloud-grafana:3300\"\n      #       iframe: true\n      #       order: 2004\n\n      #     - label: \"Arthas\"\n      #       url: \"http://localhost:9080\"\n      #       iframe: true\n      #       order: 2005', 'b1c76edb1e568732b889d665b18e8c77', '2026-09-06 09:35:56', '2026-09-06 17:35:56', 'nacos', '192.168.65.1', 'U', 'local', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (6836, 8607, 'maozi-cloud-ai-service.yml', 'DEFAULT_GROUP', '', 'project:\n  title: AI服务\n  details: 与AI交互、管理AI对话记忆、AI知识库、AI提示词等\n\napplication-port: ${application-dev-port:6000}\napplication-dubbo-port: ${application-dev-dubbo-port:20882}\n\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n# application-datasource-db-name: maozi-cloud-system-local-db\n\nspring: \n  ai: \n    # zhipuai: \n    #   base-url: https://api.z.ai/api/paas\n    #   api-key: \n    #   chat:\n    #     options:\n    #       model: glm-5.2\n    #   embedding:\n    #     enabled: false\n    dashscope: \n      api-key: ${AI_DASHSCOPE_KEY}\n      chat: \n        enabled: true\n        options: \n          model: qwen-max\n          text_image_model: qwen-vl-max\n      embedding: \n        enabled: false\n        options: \n          model: text-embedding-v3\n          dimensions: 1024\n    # openai: \n    #   base-url: \n    #   api-key: \n    #   chat: \n    #     options: \n    #       model: gpt\n    #   embedding:\n    #     enabled: false', '9669977f6c305937a712e07a3325ba15', '2026-09-06 09:36:05', '2026-09-06 17:36:05', 'nacos', '192.168.65.1', 'U', 'local', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (5648, 8608, 'maozi-cloud-oauth-service.yml', 'DEFAULT_GROUP', '', 'project:\n  title: 认证授权服务\n  details: 管理 三方认证授权、客户端 等功能\n\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n\napplication-datasource-db-name: maozi-cloud-oauth-local-db\n\napplication-redis-database: 3\n\n# application-project-whitelist: ', '0d2a62ea372d69892bf8684f78e4bd3b', '2026-09-06 09:36:24', '2026-09-06 17:36:24', 'nacos', '192.168.65.1', 'U', 'local', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (5871, 8609, 'maozi-cloud-gateway-service.yml', 'DEFAULT_GROUP', '', 'project:\n  title: 网关服务\n  details: 处理 流量分发、黑白名单、流控 等功能\n\napplication-port: ${application-dev-port:1000}\n\nspring: \n  cloud:\n    sentinel:\n      filter:\n        enabled: false\n      datasource:\n        gw-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: ${spring.cloud.nacos.config.namespace}\n            dataId: ${spring.application.name}-gw-flow\n            groupId: SENTINEL_GROUP\n            rule-type: gw-flow\n        gw-api-group:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: ${spring.cloud.nacos.config.namespace}\n            dataId: ${spring.application.name}-gw-api-group\n            groupId: SENTINEL_GROUP\n            rule-type: gw-api-group\n    gateway:\n      discovery:\n        locator:\n          enabled: true\n\n\n      default-filters:\n      - StripPrefix=1\n      - name: Retry\n        args:\n          retries: 1\n          methods: GET,POST\n          statuses: BAD_GATEWAY,GATEWAY_TIMEOUT,SERVICE_UNAVAILABLE\n          series: INFORMATIONAL\n          exceptions: java.net.ConnectException,org.springframework.cloud.gateway.support.NotFoundException\n\n\n      routes: \n        - id: MAOZI-CLOUD-SYSTEM\n          uri: lb://maozi-cloud-system-service\n          predicates:\n          - Path=/system/**\n\n        - id: MAOZI-CLOUD-OAUTH\n          uri: lb://maozi-cloud-oauth-service\n          predicates:\n          - Path=/oauth/**\n\n        - id: MAOZI-CLOUD-AI-SERVICE\n          uri: lb://maozi-cloud-ai-service\n          predicates:\n          - Path=/ai/**\n          # filters:\n          #- StripPrefix=1\n          # - WSProtocolFilter\n\n      # default-filters:\n      #   - name: Hystrix\n      #     args:\n      #       name: default\n      #       #转发地址\n      #       fallbackUri: \'forward:/fallback\'\n      #   - name: Retry\n      #     args:\n      #       #重试次数，默认值是 3 次\n      #       retries: 3\n      #       #HTTP 的状态返回码\n      #       statuses: BAD_GATEWAY,BAD_REQUEST\n      #       #指定哪些方法的请求需要进行重试逻辑，默认值是 GET 方法\n      #       methods: GET,POST', '8dda0186b10be3bcf933f00d95da8809', '2026-09-06 09:41:52', '2026-09-06 17:41:52', 'nacos', '192.168.65.1', 'U', 'dev', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (5575, 8610, 'cloud-default.yml', 'DEFAULT_GROUP', '', 'server:\n  port: ${APPLICATION_PORT:0}\n  error.path: /application/error\n  # compression:\n  #   enabled: true\n  #   min-response-size: 1024\n  #   mime-types: application/json,application/xml,text/html,text/xml,text/plain\n\nspring: \n  main:\n    banner-mode: off\n    log-startup-info: false\n  web:\n    resources:\n      add-mappings: false\n  mvc: \n    throw-exception-if-no-handler-found: true\n    pathmatch.matching-strategy: ant_path_matcher\n  jackson: \n    time-zone: GMT+8\n    date-format: yyyy-MM-dd HH:mm:ss\n    default-property-inclusion: NON_NULL\n\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n  client:\n    config:\n      default:\n        connectTimeout: 30000\n        readTimeout: 30000\n  compression:\n    request:\n      # 开启请求数据的压缩功能\n      enabled: true\n      # 最小压缩值标准，当数据大于 1024 才会进行压缩\n      min-request-size: 1024\n      # 压缩类型\n      mime-types: text/xml,application/xml,application/json\n    response:\n      enabled: true\n\nlogging: \n  level: \n    root: ERROR\n    com.maozi: INFO\n    org.apache.dubbo.registry: OFF\n    org.apache.dubbo.remoting: OFF\n    com.xxl.job.core.handler.impl.MethodJobHandler: INFO\n    org.springframework.cloud.stream.binding.StreamListenerMessageHandler: INFO', '5bc35244d5f1b046432c25d1bfbcc1f3', '2026-09-06 09:44:24', '2026-09-06 17:44:24', 'nacos', '192.168.65.1', 'U', 'local', '');
