INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (5797, 8677, 'cloud-default.yml', 'DEFAULT_GROUP', '', 'server:\n  port: ${APPLICATION_PORT:${application-port:0}}\n  error.path: /application/error\n  # compression:\n  #   enabled: true\n  #   min-response-size: 1024\n  #   mime-types: application/json,application/xml,text/html,text/xml,text/plain\n\nspring: \n  main:\n    banner-mode: off\n    log-startup-info: false\n  web:\n    resources:\n      add-mappings: false\n  mvc: \n    throw-exception-if-no-handler-found: true\n    pathmatch.matching-strategy: ant_path_matcher\n  jackson: \n    time-zone: GMT+8\n    date-format: yyyy-MM-dd HH:mm:ss\n    default-property-inclusion: NON_NULL\n\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n  client:\n    config:\n      default:\n        connectTimeout: 30000\n        readTimeout: 30000\n  compression:\n    request:\n      # 开启请求数据的压缩功能\n      enabled: true\n      # 最小压缩值标准，当数据大于 1024 才会进行压缩\n      min-request-size: 1024\n      # 压缩类型\n      mime-types: text/xml,application/xml,application/json\n    response:\n      enabled: true\n\nlogging: \n  level: \n    root: ERROR\n    com.maozi: INFO\n    org.apache.dubbo.registry: OFF\n    org.apache.dubbo.remoting: OFF\n    com.xxl.job.core.handler.impl.MethodJobHandler: INFO\n    org.springframework.cloud.stream.binding.StreamListenerMessageHandler: INFO', '4facaee32d46c7ab566ed1921474fb98', '2026-09-07 01:44:17', '2026-09-07 09:44:18', 'nacos', '192.168.65.1', 'U', 'dev', '');
