INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (5647, 8682, 'maozi-cloud-system-service.yml', 'DEFAULT_GROUP', '', 'project:\n  title: 系统服务\n  details: 管理 用户、角色、权限、系统配置 等功能\n\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n# application-datasource-db-name: maozi-cloud-system-local-db\n\napplication-project-whitelist: /config/system/get\n\napplication-project-system: \n  projectName: 小猫子脚手架\n  corporationName: 小猫子网络科技有限公司\n  icon: http://dummyimage.com/100x100\n  environment: ${environment}\n  description: 基于 Spring Cloud Alibaba + Dubbo 的一站式分布式解决方案开源封装，内置分布式应用开发所需全套组件，统一团队代码风格，保障代码质量，让开发者专注业务逻辑，实现高效快速开发。\n  copyright: 本网站所有权归《${application-project-system.corporationName}》所有，请勿抄袭和抄袭\n\nspring.servlet.multipart: \n  # 上传大小限制（默认仅 1MB）\n  max-file-size: 1MB\n  \noss:\n  # 路由到阿里云处理器\n  store-type: aliyun\n  aliyun:\n    access-key-id: ${ALIYUN_CLIENT_ID}\n    access-key-secret: ${ALIYUN_CLIENT_SECRET}\n    region: cn-beijing\n    endpoint: https://oss-cn-beijing.aliyuncs.com\n    bucket: maozi-cloud-bucket\n    #domain:                  # 可选，CDN 自定义域名', '0b03634e001a7c877af2a88305287c93', '2026-09-07 01:51:19', '2026-09-07 09:51:19', 'nacos', '192.168.65.1', 'U', 'local', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (5648, 8683, 'maozi-cloud-oauth-service.yml', 'DEFAULT_GROUP', '', 'project:\n  title: 认证授权服务\n  details: 管理 三方认证授权、客户端 等功能\n\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n\napplication-datasource-db-name: maozi-cloud-oauth-local-db\n\n# application-project-whitelist: ', '36c17f7b8b3da30aa52086fb529dcef3', '2026-09-07 01:51:27', '2026-09-07 09:51:28', 'nacos', '192.168.65.1', 'U', 'local', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (5649, 8684, 'maozi-cloud-gateway-service.yml', 'DEFAULT_GROUP', '', 'project:\n  title: 网关服务\n  details: 处理 流量分发、黑白名单、流控 等功能\n\napplication-port: 1000\n\nspring: \n  cloud:\n    sentinel:\n      filter:\n        enabled: false\n      datasource:\n        gw-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: ${spring.cloud.nacos.config.namespace}\n            dataId: ${spring.application.name}-gw-flow\n            groupId: SENTINEL_GROUP\n            rule-type: gw-flow\n        gw-api-group:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: ${spring.cloud.nacos.config.namespace}\n            dataId: ${spring.application.name}-gw-api-group\n            groupId: SENTINEL_GROUP\n            rule-type: gw-api-group\n    gateway:\n      discovery:\n        locator:\n          enabled: true\n\n\n      default-filters:\n      - StripPrefix=1\n      - name: Retry\n        args:\n          retries: 1\n          methods: GET,POST\n          statuses: BAD_GATEWAY,GATEWAY_TIMEOUT,SERVICE_UNAVAILABLE\n          series: INFORMATIONAL\n          exceptions: java.net.ConnectException,org.springframework.cloud.gateway.support.NotFoundException\n\n\n      routes: \n        - id: MAOZI-CLOUD-SYSTEM-SERVICE\n          uri: lb://maozi-cloud-system-service\n          predicates:\n          - Path=/system/**\n\n        - id: MAOZI-CLOUD-OAUTH-SERVICE\n          uri: lb://maozi-cloud-oauth-service\n          predicates:\n          - Path=/oauth/**\n\n        - id: MAOZI-CLOUD-AI-SERVICE\n          uri: lb://maozi-cloud-ai-service\n          predicates:\n          - Path=/ai/**\n          # filters:\n          #- StripPrefix=1\n          # - WSProtocolFilter\n\n      # default-filters:\n      #   - name: Hystrix\n      #     args:\n      #       name: default\n      #       #转发地址\n      #       fallbackUri: \'forward:/fallback\'\n      #   - name: Retry\n      #     args:\n      #       #重试次数，默认值是 3 次\n      #       retries: 3\n      #       #HTTP 的状态返回码\n      #       statuses: BAD_GATEWAY,BAD_REQUEST\n      #       #指定哪些方法的请求需要进行重试逻辑，默认值是 GET 方法\n      #       methods: GET,POST', '925dce890ea1958f5d0e03f69bc89aec', '2026-09-07 01:51:47', '2026-09-07 09:51:47', 'nacos', '192.168.65.1', 'U', 'local', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (5650, 8685, 'maozi-cloud-monitor-service.yml', 'DEFAULT_GROUP', '', 'project:\n  title: 监控服务\n  details: 监控 JVM、运行状态、配置、连接中间件状态 等功能\n\nspring:\n  security:\n    user:\n      name: admin\n      password: admin\n  boot:\n    admin:\n      discovery: \n        services: maozi-cloud-*\n      # ui:\n      #   external-views:\n\n      #     - label: \"Nacos\"\n      #       url: \"http://localhost:8848/nacos\"\n      #       iframe: true\n      #       order: 2002\n\n      #     - label: \"Grafana\"\n      #       url: \"http://maozi-cloud-grafana:3300\"\n      #       iframe: true\n      #       order: 2004\n\n      #     - label: \"Arthas\"\n      #       url: \"http://localhost:9080\"\n      #       iframe: true\n      #       order: 2005', 'e11d8929b244594126ceb1a2990290a1', '2026-09-07 01:52:02', '2026-09-07 09:52:02', 'nacos', '192.168.65.1', 'U', 'local', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (6836, 8686, 'maozi-cloud-ai-service.yml', 'DEFAULT_GROUP', '', 'project:\n  title: AI服务\n  details: 与AI交互、管理AI对话记忆、AI知识库、AI提示词等\n\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n# application-datasource-db-name: maozi-cloud-system-local-db\n\nspring: \n  ai: \n    # zhipuai: \n    #   base-url: https://api.z.ai/api/paas\n    #   api-key: \n    #   chat:\n    #     options:\n    #       model: glm-5.2\n    #   embedding:\n    #     enabled: false\n    dashscope: \n      api-key: ${AI_DASHSCOPE_KEY}\n      chat: \n        enabled: true\n        options: \n          model: qwen-max\n          text_image_model: qwen-vl-max\n      embedding: \n        enabled: false\n        options: \n          model: text-embedding-v3\n          dimensions: 1024\n    # openai: \n    #   base-url: \n    #   api-key: \n    #   chat: \n    #     options: \n    #       model: gpt\n    #   embedding:\n    #     enabled: false', '6e63396b2d3e7788ce4526de9ab3e2df', '2026-09-07 01:52:13', '2026-09-07 09:52:13', 'nacos', '192.168.65.1', 'U', 'local', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (5797, 8687, 'cloud-default.yml', 'DEFAULT_GROUP', '', 'server:\n  port: ${APPLICATION_PORT:${application-port:0}}\n  version: ${APPLICATION_VERSION:${application-version:main}}\n  error.path: /application/error\n  # compression:\n  #   enabled: true\n  #   min-response-size: 1024\n  #   mime-types: application/json,application/xml,text/html,text/xml,text/plain\n\nspring: \n  main:\n    banner-mode: off\n    log-startup-info: false\n  web:\n    resources:\n      add-mappings: false\n  mvc: \n    throw-exception-if-no-handler-found: true\n    pathmatch.matching-strategy: ant_path_matcher\n  jackson: \n    time-zone: GMT+8\n    date-format: yyyy-MM-dd HH:mm:ss\n    default-property-inclusion: NON_NULL\n\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n  client:\n    config:\n      default:\n        connectTimeout: 30000\n        readTimeout: 30000\n  compression:\n    request:\n      # 开启请求数据的压缩功能\n      enabled: true\n      # 最小压缩值标准，当数据大于 1024 才会进行压缩\n      min-request-size: 1024\n      # 压缩类型\n      mime-types: text/xml,application/xml,application/json\n    response:\n      enabled: true\n\nlogging: \n  level: \n    root: ERROR\n    com.maozi: INFO\n    org.apache.dubbo.registry: OFF\n    org.apache.dubbo.remoting: OFF\n    com.xxl.job.core.handler.impl.MethodJobHandler: INFO\n    org.springframework.cloud.stream.binding.StreamListenerMessageHandler: INFO', '4b7313e3456a452a268353da07acb9cd', '2026-09-07 01:52:36', '2026-09-07 09:52:36', 'nacos', '192.168.65.1', 'U', 'dev', '');
