INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (5647, 8701, 'maozi-cloud-system-service.yml', 'DEFAULT_GROUP', '', 'application:\n  title: 系统服务\n  details: 管理 用户、角色、权限、系统配置 等功能\n\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n# application-datasource-db-name: maozi-cloud-system-local-db\n\napplication-project-whitelist: /config/system/get\n\napplication-project-system: \n  projectName: 小猫子脚手架\n  corporationName: 小猫子网络科技有限公司\n  icon: http://dummyimage.com/100x100\n  environment: ${environment}\n  description: 基于 Spring Cloud Alibaba + Dubbo 的一站式分布式解决方案开源封装，内置分布式应用开发所需全套组件，统一团队代码风格，保障代码质量，让开发者专注业务逻辑，实现高效快速开发。\n  copyright: 本网站所有权归《${application-project-system.corporationName}》所有，请勿抄袭和抄袭\n\nspring.servlet.multipart: \n  # 上传大小限制（默认仅 1MB）\n  max-file-size: 1MB\n  \noss:\n  # 路由到阿里云处理器\n  store-type: aliyun\n  aliyun:\n    access-key-id: ${ALIYUN_CLIENT_ID}\n    access-key-secret: ${ALIYUN_CLIENT_SECRET}\n    region: cn-beijing\n    endpoint: https://oss-cn-beijing.aliyuncs.com\n    bucket: maozi-cloud-bucket\n    #domain:                  # 可选，CDN 自定义域名', 'd6acc319b85150dc11dfe56d62d84beb', '2026-09-07 02:45:36', '2026-09-07 10:45:37', 'nacos', '192.168.65.1', 'U', 'local', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (5869, 8702, 'maozi-cloud-system-service.yml', 'DEFAULT_GROUP', '', 'application:\n  title: 系统服务\n  details: 管理 用户、角色、权限、系统配置 等功能\n\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n# application-datasource-db-name: maozi-cloud-system-dev-db\n\napplication-project-whitelist: /config/system/get\n\napplication-project-system:\n  projectName: 小猫子脚手架\n  corporationName: 小猫子网络科技有限公司\n  icon: http://dummyimage.com/100x100\n  environment: ${environment}\n  description: 基于 Spring Cloud Alibaba + Dubbo 的一站式分布式解决方案开源封装，内置分布式应用开发所需全套组件，统一团队代码风格，保障代码质量，让开发者专注业务逻辑，实现高效快速开发。\n  copyright: 本网站所有权归《${application-project-system.corporationName}》所有，请勿抄袭和抄袭\n\nspring.servlet.multipart: \n  # 上传大小限制（默认仅 1MB）\n  max-file-size: 1MB\n  \noss:\n  # 路由到阿里云处理器\n  store-type: aliyun\n  aliyun:\n    access-key-id: ${ALIYUN_CLIENT_ID}\n    access-key-secret: ${ALIYUN_CLIENT_SECRET}\n    region: cn-beijing\n    endpoint: https://oss-cn-beijing.aliyuncs.com\n    bucket: maozi-cloud-bucket\n    #domain:                  # 可选，CDN 自定义域名', 'db48d701b821b0c7c00d313f73df88a4', '2026-09-07 02:45:49', '2026-09-07 10:45:50', 'nacos', '192.168.65.1', 'U', 'dev', '');
