INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (5798, 9943, 'cloud-dubbo.yml', 'DEFAULT_GROUP', '', 'dubbo:\n  service: \n    shutdown: \n      wait: 65000\n  # registry.register-mode: instance/interface/all\n  application: \n    name: dubbo-${spring.application.name}\n    register-mode: instance\n    version: ${application.version:main}\n    serialize-check-status: DISABLE\n    check-serializable: false\n  scan:\n    base-packages: com.maozi.${application-project-abbreviation}.*.api.impl.rpc\n  protocol:\n    # name: tri\n    name: dubbo\n    port: ${APPLICATION_DUBBO_PORT:${application.dubbo.port:-1}}\n  provider:\n    filter: applicationDubboContextLoadFilter\n    prefer-serialization: hessian2\n    serialization: hessian2\n  consumer:\n    check: false\n    timeout: 20000\n    retries: 3\n    filter: applicationDubboContextTransmitFilter\n  registry:\n    address: nacos://${spring.cloud.nacos.discovery.server-addr}?namespace=${spring.cloud.nacos.discovery.namespace}', '7e5563335d9a037b3e83eb534d8ff6f3', '2026-09-25 13:12:03', '2026-09-25 21:12:04', NULL, '172.18.0.1', 'U', 'dev', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (5871, 9944, 'maozi-cloud-gateway-service.yml', 'DEFAULT_GROUP', '', 'application:\n  port: 1100\n  title: 网关服务\n  details: 处理 流量分发、黑白名单、流控 等功能\n\nspring: \n  cloud:\n    sentinel:\n      filter:\n        enabled: false\n      datasource:\n        gw-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: ${spring.cloud.nacos.config.namespace}\n            dataId: ${spring.application.name}-gw-flow\n            groupId: SENTINEL_GROUP\n            rule-type: gw-flow\n        gw-api-group:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: ${spring.cloud.nacos.config.namespace}\n            dataId: ${spring.application.name}-gw-api-group\n            groupId: SENTINEL_GROUP\n            rule-type: gw-api-group\n\n    gateway:\n      discovery:\n        locator:\n          enabled: true\n\n      default-filters:\n      - StripPrefix=1\n      - name: Retry\n        args:\n          retries: 1\n          methods: GET,POST\n          statuses: BAD_GATEWAY,GATEWAY_TIMEOUT,SERVICE_UNAVAILABLE\n          exceptions: \n            - java.net.ConnectException\n            - org.springframework.cloud.gateway.support.NotFoundException\n\n\n      routes: \n        - id: MAOZI-CLOUD-SYSTEM\n          uri: lb://maozi-cloud-system-service\n          predicates:\n          - Path=/system/**\n\n        - id: MAOZI-CLOUD-OAUTH\n          uri: lb://maozi-cloud-oauth-service\n          predicates:\n          - Path=/oauth/**\n\n        - id: MAOZI-CLOUD-AI-SERVICE\n          uri: lb://maozi-cloud-ai-service\n          predicates:\n          - Path=/ai/**\n          # filters:\n          #- StripPrefix=1\n          # - WSProtocolFilter\n\n      # default-filters:\n      #   - name: Hystrix\n      #     args:\n      #       name: default\n      #       #转发地址\n      #       fallbackUri: \'forward:/fallback\'\n      #   - name: Retry\n      #     args:\n      #       #重试次数，默认值是 3 次\n      #       retries: 3\n      #       #HTTP 的状态返回码\n      #       statuses: BAD_GATEWAY,BAD_REQUEST\n      #       #指定哪些方法的请求需要进行重试逻辑，默认值是 GET 方法\n      #       methods: GET,POST', '8e52aea6f5177254946294586c71a037', '2026-09-25 13:17:17', '2026-09-25 21:17:17', NULL, '172.18.0.1', 'U', 'dev', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (5798, 9945, 'cloud-dubbo.yml', 'DEFAULT_GROUP', '', 'dubbo:\n\n  module.keepRunningOnSpringClosed: true\n  \n  # 该配置新版本已废弃\n  # service: \n  #   shutdown: \n  #     wait: 65000\n\n  # registry.register-mode: instance/interface/all\n  application: \n    name: dubbo-${spring.application.name}\n    register-mode: instance\n    version: ${application.version:main}\n    serialize-check-status: DISABLE\n    check-serializable: false\n  scan:\n    base-packages: com.maozi.${application-project-abbreviation}.*.api.impl.rpc\n  protocol:\n    # name: tri\n    name: dubbo\n    port: ${APPLICATION_DUBBO_PORT:${application.dubbo.port:-1}}\n  provider:\n    filter: applicationDubboContextLoadFilter\n    prefer-serialization: hessian2\n    serialization: hessian2\n  consumer:\n    check: false\n    timeout: 20000\n    retries: 3\n    filter: applicationDubboContextTransmitFilter\n  registry:\n    address: nacos://${spring.cloud.nacos.discovery.server-addr}?namespace=${spring.cloud.nacos.discovery.namespace}', '0a08cdb587fb76ff912840458f182e0d', '2026-09-25 13:21:12', '2026-09-25 21:21:12', NULL, '172.18.0.1', 'U', 'dev', '');
