INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (5798, 9956, 'cloud-dubbo.yml', 'DEFAULT_GROUP', '', 'dubbo:\n\n  module.keepRunningOnSpringClosed: true\n  \n  # 该配置新版本已废弃\n  # service: \n  #   shutdown: \n  #     wait: 65000\n\n  # registry.register-mode: instance/interface/all\n  application: \n    name: dubbo-${spring.application.name}\n    register-mode: instance\n    version: ${application.version:main}\n    serialize-check-status: DISABLE\n    check-serializable: false\n  scan:\n    base-packages: com.maozi.${application-project-abbreviation}.*.api.impl.rpc\n  protocol:\n    # name: tri\n    name: dubbo\n    port: ${APPLICATION_DUBBO_PORT:${application.dubbo.port:-1}}\n  provider:\n    filter: applicationDubboContextLoadFilter\n    prefer-serialization: hessian2\n    serialization: hessian2\n  consumer:\n    check: false\n    timeout: 20000\n    retries: 1\n    filter: applicationDubboContextTransmitFilter\n  registry:\n    address: nacos://${spring.cloud.nacos.discovery.server-addr}?namespace=${spring.cloud.nacos.discovery.namespace}', '267476bbd6e27743e9c6da3a4d1c9909', '2026-09-25 13:30:20', '2026-09-25 21:30:20', NULL, '172.18.0.1', 'U', 'dev', '');
