INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`) VALUES (5871, 11112, 'maozi-cloud-gateway-service.yml', 'DEFAULT_GROUP', '', 'application:\n  port: 1100\n  title: 网关服务\n  details: 处理 流量分发、黑白名单、流控 等功能\n\nspring: \n  cloud:\n    loadbalancer:\n      cache:\n        ttl: 5s\n    sentinel:\n      filter:\n        enabled: false\n      datasource:\n        gw-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: ${spring.cloud.nacos.config.namespace}\n            dataId: ${spring.application.name}-gw-flow\n            groupId: SENTINEL_GROUP\n            rule-type: gw-flow\n        gw-api-group:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: ${spring.cloud.nacos.config.namespace}\n            dataId: ${spring.application.name}-gw-api-group\n            groupId: SENTINEL_GROUP\n            rule-type: gw-api-group\n\n    gateway:\n      discovery:\n        locator:\n          enabled: true\n\n      default-filters:\n      - StripPrefix=1\n      - name: Retry\n        args:\n          retries: 2\n          methods: \n            - GET\n            - POST\n          statuses: \n            - BAD_GATEWAY\n            - GATEWAY_TIMEOUT\n            - SERVICE_UNAVAILABLE\n          exceptions: \n            - java.net.ConnectException\n            - org.springframework.cloud.gateway.support.NotFoundException\n            - reactor.netty.http.client.PrematureCloseException\n\n      routes: \n        - id: MAOZI-CLOUD-SYSTEM\n          uri: lb://maozi-cloud-system-service\n          predicates:\n          - Path=/system/**\n\n        - id: MAOZI-CLOUD-OAUTH\n          uri: lb://maozi-cloud-oauth-service\n          predicates:\n          - Path=/oauth/**\n\n        - id: MAOZI-CLOUD-AI-SERVICE\n          uri: lb://maozi-cloud-ai-service\n          predicates:\n          - Path=/ai/**\n          # filters:\n          #- StripPrefix=1\n          # - WSProtocolFilter\n\n      # default-filters:\n      #   - name: Hystrix\n      #     args:\n      #       name: default\n      #       #转发地址\n      #       fallbackUri: \'forward:/fallback\'\n      #   - name: Retry\n      #     args:\n      #       #重试次数，默认值是 3 次\n      #       retries: 3\n      #       #HTTP 的状态返回码\n      #       statuses: BAD_GATEWAY,BAD_REQUEST\n      #       #指定哪些方法的请求需要进行重试逻辑，默认值是 GET 方法\n      #       methods: GET,POST', 'dc76b75bd3bf195616de02a96741f294', '2026-09-27 03:43:32', '2026-09-27 11:43:32', NULL, '172.18.0.1', 'U', 'dev', '');
